// Get base data for age and gender
function getBaseData(age, gender) {
  const key = age + '_' + (gender === 'M' ? 1 : 0);
  return INSURANCE_DB[key] || null;
}

// Calculate premium multiplier (客户保费 / 标准保费100000)
// Example: 66800 / 100000 = 0.668
function getPremiumMultiplier(premium) {
  if (premium < 25000) return null; // 最低2.5万
  return premium / 100000;
}

// Get insurance data with premium adjustment and dividend rate
function getInsuranceData(age, gender, premium, dividendRate = 1.0) {
  const baseData = getBaseData(age, gender);
  if (!baseData) return null;
  
  const multiplier = getPremiumMultiplier(premium);
  if (!multiplier) return null;
  
  const data = baseData.data;
  const result = [];
  let prevGuaranteed = 0;
  let prevExpected = 0;
  
  for (let i = 0; i < data.length; i++) {
    const row = data[i];
    const year = row.year;
    
    // Apply premium multiplier
    const totalPremium = row.total_premium * multiplier;
    const guaranteed = row.guaranteed_survival * multiplier;
    const demo = row.demo_survival * multiplier;
    const deathBenefit = row.death_benefit * multiplier;
    
    // Growth rate: 本年现价 / 上年现价 - 1
    let growthRate = null;
    if (prevGuaranteed > 0) {
      growthRate = (guaranteed / prevGuaranteed) - 1;
    }
    
    // 当年分红现价 (简化计算)
    const accumDividend = demo - guaranteed;
    const currentDividendCash = accumDividend * dividendRate / year;
    const accumDividendCash = accumDividend * dividendRate;
    
    // 预期生存总利益 = 保证现价 + 累计分红现价
    const expectedSurvival = guaranteed + accumDividendCash;
    
    // 预期增长率
    let expectedRate = null;
    if (prevExpected > 0) {
      expectedRate = (expectedSurvival / prevExpected) - 1;
    }
    
    // 预期单利
    let expectedSimpleRate = null;
    if (year > 8 && totalPremium > 0 && expectedSurvival > totalPremium) {
      expectedSimpleRate = (expectedSurvival - totalPremium) / totalPremium / ((year + 8) / 2);
    }
    
    result.push({
      policy_year: year,
      age: row.age,
      premium: row.premium * multiplier,
      total_premium: totalPremium,
      death_benefit: Math.round(deathBenefit),
      cash_value: Math.round(guaranteed),
      growth_rate: growthRate,
      current_dividend_cash: Math.round(currentDividendCash),
      accum_dividend_cash: Math.round(accumDividendCash),
      demo_survival: Math.round(demo),
      demo_rate: row.demo_rate ? row.demo_rate / 100 : null,
      expected_survival: Math.round(expectedSurvival),
      expected_rate: expectedRate,
      expected_simple_rate: expectedSimpleRate,
    });
    
    prevGuaranteed = guaranteed;
    prevExpected = expectedSurvival;
  }
  
  return result;
}

// Check if age/gender combination exists
function hasData(age, gender) {
  return getBaseData(age, gender) !== null;
}

// Get available age options
function getAvailableAges(gender) {
  const ages = [];
  const genderCode = gender === 'M' ? 1 : 0;
  
  for (const key in INSURANCE_DB) {
    const [age, g] = key.split('_').map(Number);
    if (g === genderCode) {
      ages.push(age);
    }
  }
  
  return ages.sort((a, b) => a - b);
}

// Export
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { 
    getInsuranceData, 
    getBaseData, 
    hasData,
    getAvailableAges,
    getPremiumMultiplier
  };
}
